45	  token: WorkerTokenData,
46	  payload: MessagePayload,
47	  deploymentName: string,
48	): void {
49	  const matches =
50	    token.userId === payload.userId &&
51	    token.conversationId === payload.conversationId &&
52	    token.channelId === payload.channelId &&
53	    token.agentId === payload.agentId &&
54	    token.organizationId === payload.organizationId &&
55	    token.deploymentName === deploymentName &&
56	    token.runId === payload.runId &&
57	    token.messageId === payload.messageId;
58	  if (!matches) {
59	    throw new Error("Durable agent input token scope does not match payload");
60	  }
61	}
