63	export function attachFreshRunJobToken(
64	  input: PendingAgentRunInput,
65	): MessagePayload {
66	  const token = input.tokenClaims;
67	  if (
68	    !token.channelId ||
69	    !token.runId ||
70	    !token.messageId ||
71	    token.runId !== input.payload.runId ||
72	    token.messageId !== input.payload.messageId
73	  ) {
74	    throw new Error("Durable agent input has invalid run token claims");
75	  }
76	  return {
77	    ...input.payload,
78	    runJobToken: generateWorkerToken(
79	      token.userId,
80	      token.conversationId,
81	      token.deploymentName,
82	      {
83	        channelId: token.channelId,
