86	        organizationId: token.organizationId,
87	        connectionId: token.connectionId,
88	        responseThreadId: token.responseThreadId,
89	        platform: token.platform,
90	        source: token.source,
91	        sessionKey: token.sessionKey,
92	        traceId: token.traceId,
93	        runId: token.runId,
94	        messageId: token.messageId,
95	        adminTools: token.adminTools,
96	        runtimeProviderId: token.runtimeProviderId,
97	        sandboxId: token.sandboxId,
98	        allowedDomains: token.allowedDomains,
99	        deniedDomains: token.deniedDomains,
100	        nixPackages: token.nixPackages,
101	      },
102	    ),
103	  };
104	}
105	
106	export async function recordAgentRunInput(
107	  payload: MessagePayload,
108	  deploymentName: string,
109	): Promise<void> {
110	  if (!payload.organizationId || typeof payload.runId !== "number") {
111	    throw new Error("Durable agent input requires organizationId and runId");
112	  }
113	  if (!payload.runJobToken) {
114	    throw new Error("Durable agent input requires a per-run token");
115	  }
116	  const token = verifyWorkerToken(payload.runJobToken);
117	  if (!token) {
118	    throw new Error("Durable agent input requires a valid per-run token");
119	  }
120	  assertTokenMatchesInput(token, payload, deploymentName);
121	  const storedPayload = { ...payload };
122	  delete storedPayload.runJobToken;
123	  const tokenClaims = durableClaims(token);
124	  const sql = getDb();
125	  await sql`
126	    INSERT INTO public.agent_run_input (
127	      organization_id, message_id, agent_id, conversation_id,
128	      deployment_name, run_id, payload, token_claims
129	    ) VALUES (
130	      ${payload.organizationId}, ${payload.messageId}, ${payload.agentId},
131	      ${payload.conversationId}, ${deploymentName}, ${payload.runId},
132	      ${sql.json(storedPayload as unknown as Record<string, unknown>)},
133	      ${sql.json(tokenClaims as unknown as Record<string, unknown>)}
134	    )
135	    ON CONFLICT (organization_id, deployment_name, message_id) DO UPDATE SET
136	      payload = EXCLUDED.payload,
137	      token_claims = EXCLUDED.token_claims,
138	      run_id = EXCLUDED.run_id
139	    WHERE agent_run_input.status = 'pending'
140	  `;
141	}
142	
143	export async function listPendingAgentRunInputs(
144	  deploymentName: string,
145	): Promise<PendingAgentRunInput[]> {
146	  const sql = getDb();
147	  const rows = await sql<{
148	    payload: MessagePayload;
149	    token_claims: DurableRunTokenClaims;
150	  }>`
151	    SELECT input.payload, input.token_claims
152	    FROM public.agent_run_input input
153	    WHERE input.deployment_name = ${deploymentName}
154	      AND input.status = 'pending'
155	      AND EXISTS (
156	        SELECT 1
157	        FROM public.runs marker
158	        WHERE marker.status = 'pending'
159	          AND marker.run_type = 'internal'
160	          AND marker.queue_name = 'internal:turn_timeout'
161	          AND marker.action_input->>'deploymentName' = input.deployment_name
162	          AND marker.action_input->>'messageId' = input.message_id
163	          AND marker.run_at > now()
164	      )
165	    ORDER BY input.created_at, input.message_id
166	  `;
167	  return rows.map((row) => ({
168	    payload: row.payload,
169	    tokenClaims: row.token_claims,
170	  }));
171	}
172	
173	export async function completeAgentRunInputs(
174	  tx: DbClient,
175	  organizationId: string | null,
176	  deploymentName: string,
177	  messageIds: readonly string[],
178	): Promise<void> {
179	  if (!organizationId || messageIds.length === 0) return;
180	  await tx`
181	    UPDATE public.agent_run_input
182	    SET status = 'completed', completed_at = now()
183	    WHERE organization_id = ${organizationId}
184	      AND deployment_name = ${deploymentName}
185	      AND message_id = ANY(${pgTextArray([...messageIds])}::text[])
186	      AND status = 'pending'
187	  `;
188	}

