96	/**
97	 * Text of the `fetch(...)` call that STARTS at `idx`, spanning however many
98	 * physical lines it takes to balance the opening paren.
99	 *
100	 * Why not just the one line: prettier/biome split a call the moment it exceeds
101	 * the print width, so the common violation is
102	 *
103	 *   return fetch(
104	 *     "https://host/v1/chat/completions",
105	 *   );
106	 *
107	 * where no single line holds both `fetch(` and the path. Depth counting stops
108	 * at the matching `)` so an unrelated later call cannot be dragged in, and a
109	 * bounded lookahead keeps a malformed file from scanning to EOF.
110	 */
111	function completionCallText(lines, idx) {
112	  const MAX_CALL_LINES = 40;
113	  let depth = 0;
